package squirreltable

import (
	"os"
	"strings"
	"testing"
)

// TestRuntimeFileIsABuildInput pins the cause the wire pin gate exists to
// catch: squirreltable.go embeds runtime/*.nut, but the Makefile's GO_SOURCES
// names only *.go, so a runtime edit alone must still name those files as a
// prerequisite of build/schema-squirrel. Without it the corpus is generated by
// the previous emitter and the wire surface goes red on saves the source no
// longer produces (docs/PORT-SQUIRREL.md, THE HARNESS; docs/SPEC-TABLES.md §3).
func TestRuntimeFileIsABuildInput(t *testing.T) {
	t.Parallel()
	data, err := os.ReadFile("../../../make/squirrel-conformance.mk")
	if err != nil {
		t.Fatalf("read make/squirrel-conformance.mk: %v", err)
	}
	text := string(data)
	if !strings.Contains(text, "build/schema-squirrel:") ||
		!strings.Contains(text, "internal/codegen/squirreltable/runtime/*.nut") {
		t.Fatal("build/schema-squirrel does not depend on internal/codegen/squirreltable/runtime/*.nut")
	}
}
